package cn.zhuatech.b2b.service;
import jakarta.validation.constraints.*;import org.springframework.stereotype.Service;import java.util.*;
@Service public class FulfillmentRiskService {public Result evaluate(Request r){double fill=Math.min(100,r.allocatedUnits()*100.0/r.orderedUnits());int risk=(int)Math.round(Math.max(0,100-fill));List<String> actions=new ArrayList<>();if(r.supplierDelayDays()>0){risk+=Math.min(35,r.supplierDelayDays()*7);actions.add("协调供应商缩短延迟或启用替代货源");}if(r.inventoryBlocked()){risk+=45;actions.add("解除库存冻结或重新分配可用批次");}if(r.daysToPromise()<=2&&r.shippedUnits()<r.orderedUnits())risk+=25;if(r.criticalCustomer())risk+=10;risk=Math.min(100,risk);String status=risk>=70?"BLOCK_OR_NOTIFY":risk>=30?"EXPEDITE":"ON_TRACK";if(actions.isEmpty())actions.add("订单履约稳定，按承诺日期继续执行");return new Result(Math.round(fill*10)/10.0,risk,status,actions);}
 public record Request(@NotBlank String orderId,@Min(1) int orderedUnits,@Min(0) int allocatedUnits,@Min(0) int shippedUnits,@Min(0) int daysToPromise,@Min(0) int supplierDelayDays,@NotNull Boolean inventoryBlocked,@NotNull Boolean criticalCustomer){} public record Result(double fillRate,int riskScore,String status,List<String> actions){} }
